/* Host ABI: ds first, then a service callback for the unrecovered 2864
 * list helpers and the UI delay. Records are DOS DS offsets; table reads use
 * the DS copies so out-of-range indexes read the same bytes as the original.
 * Service ids: 0 wait(ticks), 1 element side(element), 2 unit side(unit),
 * 3 owning unit(element).
 */

static uint16_t word_at(const uint8_t* ds, uint16_t at) {
  return (uint16_t)(ds[at] | ds[(uint16_t)(at + 1)] << 8);
}

/* Two's-complement 16-bit wrap of DOS int arithmetic. */
static int wrap16(long value) {
  value &= 0xffffL;
  return (int)(value >= 0x8000L ? value - 0x10000L : value);
}

#define ELEMENT            uint16_t
#define UNIT               uint16_t
#define RECORD             uint16_t
