#define TYPE_BYTE(e, n)    ds[(uint16_t)(0x3332u + BYTE(e, 2) * 13u + (n))]
#define CATEGORY(e)        TYPE_BYTE(e, 4)
#define SOFT_RATING(e)     TYPE_BYTE(e, 5)
#define HARD_RATING(e)     TYPE_BYTE(e, 6)
#define RANGE(e)           TYPE_BYTE(e, 7)
#define SPEED(e)           TYPE_BYTE(e, 8)
#define MODE(e)            TYPE_BYTE(e, 11)
#define QUANTITY(e)        word_at(ds, (uint16_t)((e) + 3))
#define FATIGUE(e)         BYTE(e, 10)
#define MORALE(e)          BYTE(e, 11)
#define NEXT(e)            word_at(ds, e)
#define POS_X(e)           ds[word_at(ds, (uint16_t)((e) + 7))]
#define POS_Y(e)           BYTE(word_at(ds, (uint16_t)((e) + 7)), 1)
#define FIRST(u)           word_at(ds, u)
#define UNIT_X(u)          BYTE(u, 2)
#define UNIT_Y(u)          BYTE(u, 3)
#define SKILL(r, n)        BYTE(r, 19 + (n))
#define GARRISON           0xe946u
#define LIST(s, i)         word_at(ds, (uint16_t)(0x2fae + ((s) * 9 + (i)) * 2))
#define COMMAND(s)         word_at(ds, (uint16_t)(0x2fa8 + (s) * 2))
#define CONTROL(s)         word_at(ds, (uint16_t)(0x5e + (s) * 2))
#define MAP_X              ds[0x2fa2]
#define MAP_Y              ds[0x2fa3]
#define TERRAIN(x, y)      ds[(uint16_t)(0xcf00u + (y) * 14u + (x))]
#define FACTOR(t)          ds[(uint16_t)(0x3dae + (t))]
#define COST(t, c)         ds[(uint16_t)(0x3dfe + (t) * 8 + (c))]
#define SKILL_CLASS(t)     ds[(uint16_t)(0xb312 + (t))]
#define TERRAIN_CLASS(t)   ds[(uint16_t)(0xb31a + (t))]
#define STEP_X(d)          ds[(uint16_t)(0xb346 + (d))]
#define STEP_Y(d)          ds[(uint16_t)(0xb34a + (d))]
#define WAIT(t)            service(ds, 0, t)
#define ELEMENT_SIDE(e)    ((uint8_t)service(ds, 1, e))
#define UNIT_SIDE(u)       ((uint8_t)service(ds, 2, u))
#define ELEMENT_UNIT(e)    service(ds, 3, e)
