void opeu_battle_pause(uint8_t* ds, BattleService service, uint8_t ticks) {
  WAIT(ticks);
}

/* 000e: direction 0..7 whose grid step from the battle map origin reaches
 * the unit's map cell; 9 when none does. */
uint8_t opeu_battle_unit_direction(uint8_t* ds, BattleService service,
                                   UNIT unit) {
  uint8_t a, b, c;
  UNUSED_SERVICE;
  for (c = 0; c < 8; c++) {
    a = MAP_X;
    b = MAP_Y;
    if (opeu_grid_step(&a, &b, c) && UNIT_X(unit) == a && UNIT_Y(unit) == b)
      return c;
  }
  return 9;
}

/* 0064: skill byte of the commander responsible for an element. The second
 * garrison test is unreachable in the original as well. */
uint8_t opeu_battle_skill(uint8_t* ds, BattleService service, ELEMENT element,
                          uint8_t kind) {
  uint8_t side;
  UNIT    unit;
  RECORD  record;
  side = ELEMENT_SIDE(element);
  unit = ELEMENT_UNIT(element);
  if (COMMAND(side) || unit == GARRISON)
    record = SIDE_RECORD(side, 1);
  else if (unit == GARRISON)
    record = SIDE_RECORD(side, 2);
  else
    record = GROUP_RECORD(side, opeu_unit_group_index(unit));
  switch (kind) {
    case 0: return SKILL(record, 0);
    case 1: return SKILL(record, 1);
    case 2: return SKILL(record, 2);
    case 3: return SKILL(record, 3);
    case 4: return SKILL(record, 5);
    case 5: return SKILL(record, 6);
    case 6: return SKILL(record, 7);
    case 7: return SKILL(record, 8);
  }
  return 0;
}

uint8_t opeu_battle_element_strength(uint8_t* ds, BattleService service,
                                     ELEMENT element) {
  int     a;
  uint8_t b, c;
  c = CATEGORY(element);
  if (c == 4 && MODE(element) <= 1)
    c = 3;
  b = SKILL_OF(element, 7) / 5;
  switch (SKILL_CLASS(c)) {
    case 0: ADD_BYTE(SKILL_OF(element, 4), &b); break;
    case 1: ADD_BYTE(SKILL_OF(element, 5), &b); break;
    case 2: ADD_BYTE(SKILL_OF(element, 6), &b); break;
  }
  b /= 10;
  a = (MORALE(element) / 30 - FATIGUE(element) / 20 + 10) * (FACTOR(c) / 10) -
      b;
  if (a < 5)
    a = 5;
  if (a > 255)
    a = 255;
  return (uint8_t)a;
}

uint8_t opeu_battle_odds(uint8_t* ds, BattleService service, uint8_t rating,
                         uint8_t range) {
  int r;
  (void)ds;
  (void)service;
  r = rating - range + 30;
  if (r <= 0) {
    if (r > -15)
      r = 1;
    else
      r = 0;
  }
  if (r >= 100)
    r = 99;
  return (uint8_t)r;
}

uint8_t opeu_battle_element_rating(uint8_t* ds, BattleService service,
                                   ELEMENT attacker, ELEMENT target) {
  UNUSED_SERVICE;
  if (!target || CATEGORY(target) != 3)
    return HARD_RATING(attacker);
  return SOFT_RATING(attacker);
}

uint8_t opeu_battle_element_range(uint8_t* ds, BattleService service,
                                  ELEMENT element) {
  UNUSED_SERVICE;
  if (!element)
    return 20;
  return RANGE(element);
}

uint8_t opeu_battle_element_shots(uint8_t* ds, BattleService service,
                                  ELEMENT attacker, ELEMENT target) {
  uint8_t a;
  UNUSED_SERVICE;
  if (CATEGORY(attacker) == 0) {
    if (!target || CATEGORY(target) == 0)
      a = QUANTITY(attacker) / 10;
    else
      a = QUANTITY(attacker) / 50;
    if (!a)
      return 1;
    return a;
  }
  return (uint8_t)QUANTITY(attacker);
}

uint8_t opeu_battle_cell_terrain(uint8_t* ds, BattleService service, uint8_t x,
                                 uint8_t y) {
  uint8_t a;
  UNUSED_SERVICE;
  a = TERRAIN(x, y) & 0x3f;
  return TERRAIN_CLASS(a);
}

uint16_t opeu_battle_can_enter(uint8_t* ds, BattleService service, uint8_t x,
                               uint8_t y, ELEMENT element) {
  if (COST(TERRAIN_AT(x, y), CATEGORY(element)) != 255)
    return 1;
  return 0;
}

/* 03a4: 255 for impassable terrain, else a cost clamped to 5..250. The
 * product is 16-bit int arithmetic in the original. */
uint8_t opeu_battle_move_cost(uint8_t* ds, BattleService service, uint8_t x,
                              uint8_t y, ELEMENT element) {
  int     a, c, d;
  uint8_t b, e;
  b = CATEGORY(element);
  if ((e = COST(TERRAIN_AT(x, y), b)) == 255)
    return e;
  d = SKILL_OF(element, 7) / 5;
  d += SKILL_OF(element, 0);
  d = d / 20 - 2;
  d += FATIGUE(element) / 20 - 1;
  d -= MORALE(element) / 20;
  a = SPEED(element);
  switch (b) {
    case 0: a <<= 1; break;
  }
  c = (MUL16(MUL16((100 - a) / 3, e), 10) /
           ((int)opeu_max16(COST(0, b), 1) * 10) -
       d) /
      2;
  if (c < 5)
    c = 5;
  if (c > 250)
    c = 250;
  return (uint8_t)c;
}

void opeu_battle_step_unchecked(uint8_t* ds, BattleService service, uint8_t* x,
                                uint8_t* y, uint8_t direction) {
  UNUSED_SERVICE;
  if (direction < 4) {
    *x += STEP_X(direction) - 1;
    *y += STEP_Y(direction) - 1;
  }
}

uint16_t opeu_battle_step(uint8_t* ds, BattleService service, uint8_t* x,
                          uint8_t* y, uint8_t direction) {
  uint8_t next_x = *x, next_y = *y;
  STEP(&next_x, &next_y, direction);
  if (next_x < 14 && next_y < 14) {
    *x = next_x;
    *y = next_y;
    return 1;
  }
  return 0;
}

uint16_t opeu_battle_unit_controlled(uint8_t* ds, BattleService service,
                                     UNIT unit) {
  uint8_t side = UNIT_SIDE(unit);
  if (COMMAND(side) && CONTROL(side) == 1)
    return 1;
  return 0;
}

ELEMENT opeu_battle_element_at(uint8_t* ds, BattleService service, uint8_t x,
                               uint8_t y) {
  UNIT    a;
  ELEMENT b;
  uint8_t c, d;
  UNUSED_SERVICE;
  for (c = 0; c < 2; c++)
    for (d = 0; d < 9; d++)
      if ((a = LIST(c, d)) != 0)
        for (b = FIRST(a); b; b = NEXT(b))
          if (POS_X(b) == x && POS_Y(b) == y)
            return b;
  return 0;
}

/* ---- services (native build) ----------------------------------------
 * The host branch above reports each call that leaves the module to its
 * service callback. In the native build every service is the direct call
 * below (tools/game-services.json): the routine the original called, with
 * the conversions of the 16-bit memory model (DS offsets, far pointers,
 * the modeled stack of port/include/glue.h). The validators build with
 * -DOPEU_HOST_EVENTS and see only the host branch. */

/* Services of map/btlcalc.c (2864, battle calculations). BattleService ids of the
 * host branch (src/main/map/btlcalc.c WAIT / ELEMENT_SIDE / UNIT_SIDE /
 * ELEMENT_UNIT; tests/validate_battle_calc.py):
 *   0 wait(ticks)         0a8e:004c delay_units (WAITKEY)
 *   1 element_side(e)     2864:000e battle_element_side (BTLLIST)
 *   2 unit_side(u)        2864:001c battle_unit_side (BTLLIST)
 *   3 element_unit(e)     2864:002c battle_element_unit (BTLLIST) */
uint16_t svc_btlcalc(uint8_t* ds, uint16_t id, uint16_t arg) {
  switch (id) {
    case 0:  opeu_delay_units(ds, svc_waitkey, (uint8_t)arg); return 0;
    case 1:  return opeu_battle_element_side(ds, svc_btllist, arg);
    case 2:  return opeu_battle_unit_side(ds, svc_btllist, arg);
    case 3:  return opeu_battle_element_unit(ds, svc_btllist, arg);
    default: port_unhandled("btlcalc", id, 1); return 0;
  }
}

